#!/usr/bin/env node
// -----------------------------------------------------------------------------
// Regenerates src/lifx/products-data.js from the official LIFX product
// registry (`products.json` of https://github.com/LIFX/products), so a new
// LIFX model gets its capabilities and its white range.
//
//   git clone --depth 1 https://github.com/LIFX/products /tmp/lifx-products
//   node tools/update-products.mjs /tmp/lifx-products/products.json
//
// The generated file is left out of Prettier (.prettierignore): one product
// per line keeps its diffs readable.
//
// Only what the integration reads is kept: the name of each product, the
// capabilities that change its Gladys device, and the firmware upgrades that
// change them. Development tool: the image never runs it.
// -----------------------------------------------------------------------------

import { readFile, writeFile } from 'node:fs/promises';

const KEPT = [
  'color',
  'infrared',
  'multizone',
  'extended_multizone',
  'matrix',
  'chain',
  'hev',
  'relays',
  'buttons',
  'temperature_range',
];

const source = process.argv[2];
if (!source) {
  console.error('Usage: node tools/update-products.mjs <path to products.json>');
  process.exit(1);
}

const registry = JSON.parse(await readFile(source, 'utf8'));
const lifx = registry.find((vendor) => vendor.vid === 1);
if (!lifx) {
  console.error('No LIFX vendor (vid 1) in this file');
  process.exit(1);
}

const pick = (features) =>
  Object.fromEntries(KEPT.filter((key) => key in features).map((key) => [key, features[key]]));

const products = lifx.products.map((product) => ({
  pid: product.pid,
  name: product.name,
  // The defaults are all false: only the capabilities a product has.
  features: Object.fromEntries(
    Object.entries(pick(product.features)).filter(
      ([key, value]) => key === 'temperature_range' || value === true,
    ),
  ),
  upgrades: product.upgrades
    .map((upgrade) => ({
      major: upgrade.major,
      minor: upgrade.minor,
      features: pick(upgrade.features),
    }))
    .filter((upgrade) => Object.keys(upgrade.features).length > 0),
}));

const lines = [
  '// Generated by tools/update-products.mjs from the LIFX product registry',
  '// (https://github.com/LIFX/products, LIFX Developer Terms). Do not edit by hand.',
  '',
  `export const DEFAULT_FEATURES = ${JSON.stringify(pick(lifx.defaults))};`,
  '',
  'export const PRODUCTS = [',
  ...products.map((product) => `  ${JSON.stringify(product)},`),
  '];',
  '',
];
await writeFile(new URL('../src/lifx/products-data.js', import.meta.url), lines.join('\n'));
console.log(`${products.length} LIFX products written`);
